function renderFrame(){if(!timeline)return;if(page==='power'||page==='after')monitorPanels.get(page).render();if(sensorMode()){if(page==='overview')forcePanels.get('force-overview').render();if(page==='scope')forcePanels.get('force-scope').render();}for(const def of gaugeDefs)if(page==='overview')renderGaugeOptions(def,valueFor(def.key,cursor));$('record-clock').textContent='数据时刻：'+clock(cursor);$('speed-value').textContent=fmt(valueFor('WheelBasedVehicleSpeed',cursor));$('coolant-value').textContent=fmt(valueFor('EngCoolantTemp',cursor));$('oil-value').textContent=fmt(valueFor('EngOilPress',cursor),0);$('fuel-total-value').textContent=fmt(valueFor('IntegratedFuel_L',cursor),3);renderMetricFreshness();currentGPS=mapPointAt(cursor);if(page==='overview'){if(!sensorMode())renderOverview();const e=initMap('mini-map');updateMap(e,cursor);renderGPS();}if(page==='scope'&&!sensorMode())renderScopes();if(page==='map'){const e=initMap('large-map');updateMap(e,cursor);renderGPS();}$('elapsed-time').textContent=elapsed(cursor-timeline.start);$('duration-time').textContent=elapsed(timeline.end-timeline.start);$('time-slider').value=timeline.end===timeline.start?0:(cursor-timeline.start)/(timeline.end-timeline.start)*1000;$('play-pause').textContent=playing?'Ⅱ':'▶';$('play-pause').setAttribute('aria-label',playing?'暂停播放':'开始播放');$('playback-state').textContent=live?(liveHasData?'实时数据':'等待实时数据'):playing?($('loop-play').checked?'循环回放':'正在回放'):'已暂停';}
