 const rows=receptionJournal.rows.map(e=>[e.id,formatBeijing(e.time),e.status,e.bytes,e.frames,e.can,e.targetFrames,(e.keys||[]).join(';'),e.validGPS,e.gps,e.bad,e.malformed,e.discarded,e.detail]);
 const header=['序号','接收观察时间_北京时间','结果','新增字节','有效帧','CAN帧','含有效目标信号的CAN帧','有效信号名','有效GPS帧','GPS帧','校验失败','格式异常','丢弃字节','说明'];
